-- CS336 Project 2 - Group 28
-- Step 4: rebuild the original CSV from the normalized tables only (the
-- Preliminary table is NOT used). Writes reconstructed2.csv.
--
-- Run with:  psql -f 03_export_csv.sql
-- Verify with:  diff hmda_2017_nj_all-records_labels.csv reconstructed2.csv
--
-- Same output technique as Project 1: every field is quoted (FORCE_QUOTE *),
-- blanks come from coalesce(x, '') so they are written as "", rate_spread is
-- re-padded to NN.NN with to_char, and the blank sequence_number column is
-- written as ''. Rows come back in the original order (ORDER BY sequence_number).
-- \copy must stay on a single line.

\copy (SELECT coalesce(a.as_of_year::text, '') AS as_of_year, coalesce(a.respondent_id::text, '') AS respondent_id, coalesce(ag.agency_name, '') AS agency_name, coalesce(ag.agency_abbr, '') AS agency_abbr, coalesce(a.agency_code::text, '') AS agency_code, coalesce(lt.loan_type_name, '') AS loan_type_name, coalesce(a.loan_type::text, '') AS loan_type, coalesce(pt.property_type_name, '') AS property_type_name, coalesce(a.property_type::text, '') AS property_type, coalesce(lp.loan_purpose_name, '') AS loan_purpose_name, coalesce(a.loan_purpose::text, '') AS loan_purpose, coalesce(oo.owner_occupancy_name, '') AS owner_occupancy_name, coalesce(a.owner_occupancy::text, '') AS owner_occupancy, coalesce(a.loan_amount_000s::text, '') AS loan_amount_000s, coalesce(pa.preapproval_name, '') AS preapproval_name, coalesce(a.preapproval::text, '') AS preapproval, coalesce(at.action_taken_name, '') AS action_taken_name, coalesce(a.action_taken::text, '') AS action_taken, coalesce(m.msamd_name, '') AS msamd_name, coalesce(l.msamd::text, '') AS msamd, coalesce(s.state_name, '') AS state_name, coalesce(s.state_abbr, '') AS state_abbr, coalesce(l.state_code::text, '') AS state_code, coalesce(c.county_name, '') AS county_name, coalesce(l.county_code::text, '') AS county_code, coalesce(l.census_tract_number::text, '') AS census_tract_number, coalesce(ae.ethnicity_name, '') AS applicant_ethnicity_name, coalesce(a.applicant_ethnicity::text, '') AS applicant_ethnicity, coalesce(ce.ethnicity_name, '') AS co_applicant_ethnicity_name, coalesce(a.co_applicant_ethnicity::text, '') AS co_applicant_ethnicity, coalesce(ar1n.race_name, '') AS applicant_race_name_1, coalesce(ar1.applicant_race::text, '') AS applicant_race_1, coalesce(ar2n.race_name, '') AS applicant_race_name_2, coalesce(ar2.applicant_race::text, '') AS applicant_race_2, coalesce(ar3n.race_name, '') AS applicant_race_name_3, coalesce(ar3.applicant_race::text, '') AS applicant_race_3, coalesce(ar4n.race_name, '') AS applicant_race_name_4, coalesce(ar4.applicant_race::text, '') AS applicant_race_4, coalesce(ar5n.race_name, '') AS applicant_race_name_5, coalesce(ar5.applicant_race::text, '') AS applicant_race_5, coalesce(cr1n.race_name, '') AS co_applicant_race_name_1, coalesce(cr1.co_applicant_race::text, '') AS co_applicant_race_1, coalesce(cr2n.race_name, '') AS co_applicant_race_name_2, coalesce(cr2.co_applicant_race::text, '') AS co_applicant_race_2, coalesce(cr3n.race_name, '') AS co_applicant_race_name_3, coalesce(cr3.co_applicant_race::text, '') AS co_applicant_race_3, coalesce(cr4n.race_name, '') AS co_applicant_race_name_4, coalesce(cr4.co_applicant_race::text, '') AS co_applicant_race_4, coalesce(cr5n.race_name, '') AS co_applicant_race_name_5, coalesce(cr5.co_applicant_race::text, '') AS co_applicant_race_5, coalesce(as_.sex_name, '') AS applicant_sex_name, coalesce(a.applicant_sex::text, '') AS applicant_sex, coalesce(cs.sex_name, '') AS co_applicant_sex_name, coalesce(a.co_applicant_sex::text, '') AS co_applicant_sex, coalesce(a.applicant_income_000s::text, '') AS applicant_income_000s, coalesce(pu.purchaser_type_name, '') AS purchaser_type_name, coalesce(a.purchaser_type::text, '') AS purchaser_type, coalesce(dr1n.denial_reason_name, '') AS denial_reason_name_1, coalesce(dr1.denial_reason::text, '') AS denial_reason_1, coalesce(dr2n.denial_reason_name, '') AS denial_reason_name_2, coalesce(dr2.denial_reason::text, '') AS denial_reason_2, coalesce(dr3n.denial_reason_name, '') AS denial_reason_name_3, coalesce(dr3.denial_reason::text, '') AS denial_reason_3, coalesce(to_char(a.rate_spread, 'FM00.00'), '') AS rate_spread, coalesce(ho.hoepa_status_name, '') AS hoepa_status_name, coalesce(a.hoepa_status::text, '') AS hoepa_status, coalesce(li.lien_status_name, '') AS lien_status_name, coalesce(a.lien_status::text, '') AS lien_status, coalesce(n.edit_status_name::text, '') AS edit_status_name, coalesce(n.edit_status::text, '') AS edit_status, coalesce(''::text, '') AS sequence_number, coalesce(l.population::text, '') AS population, coalesce(l.minority_population::text, '') AS minority_population, coalesce(l.hud_median_family_income::text, '') AS hud_median_family_income, coalesce(l.tract_to_msamd_income::text, '') AS tract_to_msamd_income, coalesce(l.number_of_owner_occupied_units::text, '') AS number_of_owner_occupied_units, coalesce(l.number_of_1_to_4_family_units::text, '') AS number_of_1_to_4_family_units, coalesce(n.application_date_indicator::text, '') AS application_date_indicator FROM application a JOIN agency ag ON ag.agency_code = a.agency_code JOIN loan_type lt ON lt.loan_type = a.loan_type JOIN property_type pt ON pt.property_type = a.property_type JOIN loan_purpose lp ON lp.loan_purpose = a.loan_purpose JOIN owner_occupancy oo ON oo.owner_occupancy = a.owner_occupancy JOIN preapproval pa ON pa.preapproval = a.preapproval JOIN action_taken at ON at.action_taken = a.action_taken JOIN purchaser_type pu ON pu.purchaser_type = a.purchaser_type JOIN hoepa_status ho ON ho.hoepa_status = a.hoepa_status JOIN lien_status li ON li.lien_status = a.lien_status JOIN ethnicity ae ON ae.ethnicity = a.applicant_ethnicity JOIN ethnicity ce ON ce.ethnicity = a.co_applicant_ethnicity JOIN sex as_ ON as_.sex = a.applicant_sex JOIN sex cs ON cs.sex = a.co_applicant_sex JOIN location l ON l.location_id = a.location_id JOIN state s ON s.state_code = l.state_code LEFT JOIN county c ON c.state_code = l.state_code AND c.county_code = l.county_code LEFT JOIN msamd m ON m.msamd = l.msamd LEFT JOIN applicant_race ar1 ON ar1.sequence_number = a.sequence_number AND ar1.race_number = 1 LEFT JOIN race ar1n ON ar1n.race = ar1.applicant_race LEFT JOIN co_applicant_race cr1 ON cr1.sequence_number = a.sequence_number AND cr1.race_number = 1 LEFT JOIN race cr1n ON cr1n.race = cr1.co_applicant_race LEFT JOIN applicant_race ar2 ON ar2.sequence_number = a.sequence_number AND ar2.race_number = 2 LEFT JOIN race ar2n ON ar2n.race = ar2.applicant_race LEFT JOIN co_applicant_race cr2 ON cr2.sequence_number = a.sequence_number AND cr2.race_number = 2 LEFT JOIN race cr2n ON cr2n.race = cr2.co_applicant_race LEFT JOIN applicant_race ar3 ON ar3.sequence_number = a.sequence_number AND ar3.race_number = 3 LEFT JOIN race ar3n ON ar3n.race = ar3.applicant_race LEFT JOIN co_applicant_race cr3 ON cr3.sequence_number = a.sequence_number AND cr3.race_number = 3 LEFT JOIN race cr3n ON cr3n.race = cr3.co_applicant_race LEFT JOIN applicant_race ar4 ON ar4.sequence_number = a.sequence_number AND ar4.race_number = 4 LEFT JOIN race ar4n ON ar4n.race = ar4.applicant_race LEFT JOIN co_applicant_race cr4 ON cr4.sequence_number = a.sequence_number AND cr4.race_number = 4 LEFT JOIN race cr4n ON cr4n.race = cr4.co_applicant_race LEFT JOIN applicant_race ar5 ON ar5.sequence_number = a.sequence_number AND ar5.race_number = 5 LEFT JOIN race ar5n ON ar5n.race = ar5.applicant_race LEFT JOIN co_applicant_race cr5 ON cr5.sequence_number = a.sequence_number AND cr5.race_number = 5 LEFT JOIN race cr5n ON cr5n.race = cr5.co_applicant_race LEFT JOIN application_denial dr1 ON dr1.sequence_number = a.sequence_number AND dr1.denial_reason_number = 1 LEFT JOIN denial_reason dr1n ON dr1n.denial_reason = dr1.denial_reason LEFT JOIN application_denial dr2 ON dr2.sequence_number = a.sequence_number AND dr2.denial_reason_number = 2 LEFT JOIN denial_reason dr2n ON dr2n.denial_reason = dr2.denial_reason LEFT JOIN application_denial dr3 ON dr3.sequence_number = a.sequence_number AND dr3.denial_reason_number = 3 LEFT JOIN denial_reason dr3n ON dr3n.denial_reason = dr3.denial_reason CROSS JOIN all_null_columns n ORDER BY a.sequence_number) TO 'reconstructed2.csv' WITH (FORMAT csv, HEADER true, FORCE_QUOTE *)
